export interface Task {
  id: string;
  title: string;
  completed: boolean;
}

let tasks: Task[] = [];
let nextId = 1;

export function resetStore(): void {
  tasks = [];
  nextId = 1;
}

export function listTasks(filter?: { completed?: boolean }): Task[] {
  if (filter && typeof filter.completed === "boolean") {
    return tasks.filter((t) => t.completed === filter.completed);
  }
  return [...tasks];
}

export function createTask(input: { title: string; completed?: boolean }): Task {
  const task: Task = {
    id: String(nextId++),
    title: input.title,
    completed: input.completed ?? false,
  };
  tasks.push(task);
  return task;
}

export function updateTask(id: string, patch: Partial<Pick<Task, "title" | "completed">>): Task | undefined {
  const task = tasks.find((t) => t.id === id);
  if (!task) return undefined;
  if (patch.title !== undefined) task.title = patch.title;
  if (patch.completed !== undefined) task.completed = patch.completed;
  return task;
}

export function deleteTask(id: string): boolean {
  const index = tasks.findIndex((t) => t.id === id);
  if (index === -1) return false;
  tasks.splice(index, 1);
  return true;
}

export interface ValidateResult {
  valid: boolean;
  errors: string[];
}

export function validateTask(
  input: { title?: unknown; completed?: unknown },
  opts: { partial: boolean }
): ValidateResult {
  const errors: string[] = [];

  const titleProvided = input.title !== undefined;

  if (!titleProvided) {
    if (!opts.partial) {
      errors.push("title is required");
    }
  } else {
    if (typeof input.title !== "string") {
      errors.push("title must be a string");
    } else {
      const trimmed = input.title.trim();
      if (trimmed.length === 0) {
        errors.push("title must not be empty");
      }
      if (input.title.length > 100) {
        errors.push("title must be at most 100 characters");
      }
    }
  }

  if (input.completed !== undefined && typeof input.completed !== "boolean") {
    errors.push("completed must be a boolean");
  }

  return { valid: errors.length === 0, errors };
}

import { Router, Request, Response } from "express";
import { listTasks, createTask, updateTask, deleteTask } from "./store.js";
import { validateTask } from "./validate.js";

export const router = Router();

router.get("/", (req: Request, res: Response) => {
  const { completed } = req.query;
  if (completed === undefined) {
    return res.json(listTasks());
  }
  const completedBool = completed === "true";
  res.json(listTasks({ completed: completedBool }));
});

router.post("/", (req: Request, res: Response) => {
  const result = validateTask(req.body ?? {}, { partial: false });
  if (!result.valid) {
    return res.status(400).json({ errors: result.errors });
  }
  const task = createTask({ title: req.body.title, completed: req.body.completed });
  res.status(201).json(task);
});

router.patch("/:id", (req: Request, res: Response) => {
  const result = validateTask(req.body ?? {}, { partial: true });
  if (!result.valid) {
    return res.status(400).json({ errors: result.errors });
  }
  const task = updateTask(req.params.id, {
    title: req.body.title,
    completed: req.body.completed,
  });
  if (!task) {
    return res.status(404).json({ error: "not found" });
  }
  res.json(task);
});

router.delete("/:id", (req: Request, res: Response) => {
  const deleted = deleteTask(req.params.id);
  if (!deleted) {
    return res.status(404).json({ error: "not found" });
  }
  res.status(204).send();
});

import express from "express";
import { router } from "./routes.js";

export function createApp() {
  const app = express();
  app.use(express.json());
  app.use("/tasks", router);
  return app;
}

import { createApp } from "./app.js";

const port = process.env.PORT ? Number(process.env.PORT) : 3000;
createApp().listen(port, () => {
  console.log(`tasks-api listening on :${port}`);
